window.__F=window.__F||{};window.__F["bf-02.html"]="<div class=\"ac-info\"><p class=\"ac-i-main\">دليل الهيكل الأساسي والصدّامات: قائمة العدد الخاصة ومواصفات العزوم، ثم لكل جزء فك وتركيب (ماصّ الصدمة، الصدّام، الواجهة الأمامية والخلفية، والدعامات).</p><p class=\"ac-i-tip\"><b>متى تستعمله:</b> استعمله عند إصلاح الحوادث أو استبدال الصدّام والواجهات. راجع عزوم الشد قبل التركيب.</p></div><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">1</span><span class=\"ct-ttl\"><strong dir=\"ltr\">SPECIAL TOOLS</strong><small>العدد الخاصة</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><p style=\"margin-inline-start:40px\">8534C - Fixture, Driveline Support (Originally Shipped In Kit Number(s) 8534, 8534B, 8849, 9565.)</p><p style=\"margin-inline-start:40px\">9031-1 - Bushing Removal Receiver (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-10 - Brace (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-11 - Clamp (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-12 - Brace (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-2 - Remover, Bushing (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-3 - Receiver, Bushing (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-4 - Installer, Bushing (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-5A - Remover, Bushing (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-6 - Receiver (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-7A - Installer, Bushing (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-8A - Receiver, Bushing (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9031-9 - Clamp (Originally Shipped In Kit Number(s) 9074, 9076, 9090, 9329-SUP, 9396, 9515- SUP, 9516-SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9032-1 - Receiver, Bushing (Originally Shipped In Kit Number(s) 9076, 9090, 9090CC.)</p><p style=\"margin-inline-start:0px\">9032-2 - Receiver, Bushing (Originally Shipped In Kit Number(s) 9076, 9090, 9090CC.)</p><p style=\"margin-inline-start:0px\">9032-3 - Pusher, Bushing (Originally Shipped In Kit Number(s) 9076, 9090, 9090CC.)</p><p style=\"margin-inline-start:0px\">9360 - Remover, Ball Joint (Originally Shipped In Kit Number(s) 9329, 9515, 9516, 9516-CAN, 9517, 9517-CAN, 9518, 9519, 9540, 9541.)</p><p style=\"margin-inline-start:0px\">9520 - Remover/Installer, Bushing (Originally Shipped In Kit Number(s) 9329, 9329-SUP, 9515-SUP, 9516, 9516- SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9520-1 - Installer Disc (Originally Shipped In Kit Number(s) 9329, 9329-SUP, 9515-SUP, 9516, 9516- SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9520-2A - Installer, Bushing (Originally Shipped In Kit Number(s) 9329, 9329-SUP, 9515-SUP, 9516, 9516- SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9520-3 - Remover, Bushing (Originally Shipped In Kit Number(s) 9329, 9329-SUP, 9515-SUP, 9516, 9516- SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:0px\">9520-4 - Cup, Receiver (Originally Shipped In Kit Number(s) 9329, 9329-SUP, 9515-SUP, 9516, 9516- SUP, 9517-SUP, 9518, 9519, 9540-SUP, 9541-SUP.)</p><p style=\"margin-inline-start:40px\">C-4212F - Press, Ball Joint (Originally Shipped In Kit Number(s) 6745, 6880, 6881, MLR-C03.)</p></div><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">TECHNICAL SPECIFICATIONS</strong><small>المواصفات الفنية</small></span></summary><div class=\"ct-body\"></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">TORQUE SPECIFICATIONS</strong><small>عزوم الشد</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><pre class=\"en-pre\">DESCRIPTION                       N.m    Ft. Lbs.        In. Lbs.        COMMENT\nEngine cradle bolts (long)        185      136               -              \nEngine cradle bolts (short)       180      133               -              \nFront bumper bolts                 28       21               -              \nRear bumper nuts                   27       20               -              \nRear suspension crossmember to\n                                  185      136               -                \nbody bolts (long)\nRear suspension crossmember to\n                                  180      133               -                \nbody bolts (short)\nTransmission Crossmember Bolts     61      45                -                \nTransmission Crossmember to\n                                   61      45                -                \nMount Bolts</pre></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">3</span><span class=\"ct-ttl\"><strong dir=\"ltr\">ABSORBER, FRONT ENERGY</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Remove the front fascia Refer to FASCIA, FRONT, REMOVAL.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove the two screws (1).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the push pin fasteners (2) and remove the absorber.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Install the absorber (1) Install the push pin fasteners (2).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Install the screws (1).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Install the front fascia Refer to FASCIA, FRONT, INSTALLATION.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">4</span><span class=\"ct-ttl\"><strong dir=\"ltr\">ABSORBER, REAR ENERGY</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Remove the rear fascia Refer to FASCIA, REAR, REMOVAL.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove the push pin fasteners (2) and remove the absorber (1)</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Install the energy absorber (1) and install the push pin fasteners (2).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Install the rear fascia Refer to FASCIA, REAR, INSTALLATION.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">5</span><span class=\"ct-ttl\"><strong dir=\"ltr\">BUMPER, FRONT</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Remove fascia assembly. Refer to FASCIA, FRONT, REMOVAL.</span></div><div class=\"ct-note en-kw\">NOTE:          There are welded tabs that temporarily hold the bumper beam in place before the bolts are installed at the factory. The welds have to be drilled out before the bumper can be removed. The tabs do not need to be re- welded for installation.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove the eight screws (4 per side) and remove the bumper.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-note en-kw\">NOTE:          There are welded tabs that temporarily hold the bumper beam in place before</div><p style=\"margin-inline-start:30px\">the bolts are installed at the factory. The welds have to be drilled out before the bumper can be removed. The tabs do not need to be re-welded for installation.</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Position the bumper.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Install the bolts and tighten to the proper torque specifications. Refer to TORQUE SPECIFICATIONS.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Install the fascia. Refer to FASCIA, FRONT, INSTALLATION.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">6</span><span class=\"ct-ttl\"><strong dir=\"ltr\">BUMPER, REAR</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Remove the fascia assembly. Refer to FASCIA, REAR, REMOVAL.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove the six nuts and washers and remove the bumper.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Position the bumper.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Install the nuts and washers and tighten to the proper torque specifications. Refer to TORQUE SPECIFICATIONS.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Install the fascia assembly. Refer to FASCIA, REAR, INSTALLATION.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">7</span><span class=\"ct-ttl\"><strong dir=\"ltr\">FASCIA, FRONT</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Raise and support the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove the 12 upper radiator fasteners (1).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the upper fender to fascia bolts (1) from each side.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Remove the front wheelhouse splash shields, Refer to SHIELD, SPLASH, REAR WHEELHOUSE, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Remove the engine belly pan, Refer to BELLY PAN, REMOVAL.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Remove the fascia to fender screws (1) from both sides.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Disconnect the marker light electrical connectors (1).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Disconnect the fog lamps (1), if equipped.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Pull the sides of the front fascia (2) to disengage the retainers (3), then pull the front fascia forward and remove.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Carefully position the front fascia (2) onto the vehicle, aligning fender the studs as seating it fully.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Hand tap the front fascia to engage the fender retaining clips.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Install the fascia to fender screws and tighten to the proper torque specifications. Refer to TORQUE SPECIFICATIONS .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Connect the marker light electrical connectors (1).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Connect the fog lamp electrical connectors (1).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Install the front wheelhouse splash shields, Refer to SHIELD, SPLASH, REAR WHEELHOUSE, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Install the belly pans, Refer to BELLY PAN, REMOVAL.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Install the upper fender to fascia bolts (1) on each side and tighten to the proper torque specifications.</span></div><p style=\"margin-inline-start:0px\">Refer to TORQUE SPECIFICATIONS .</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Install the 12 front upper push pin fasteners (1).</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">8</span><span class=\"ct-ttl\"><strong dir=\"ltr\">FASCIA, REAR</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Disconnect the negative battery cable.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Raise and support the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the three push-pin retainers that secure each rear wheel house splash shield to the rear fascia assembly.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Remove the fastener (1) that secures the rear fascia assembly to the rear quarter.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Pull down on the end of the bracket (2) to allow the fascia to be pulled out.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Remove the fasteners (3) that secures the rear fascia assembly to the rear fascia support bracket.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Remove the taillamps, Refer to LAMP, TAIL STOP TURN, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Pull out on the fascia (2) at the wheel house opening to disengage the fascia from the retaining bracket. Repeat on the opposite side.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>With the help of an assistant, pull rearward to disengage the fascia (1) from the rear retaining bracket. Do not completely remove at this time.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">10</span><span>Disconnect the marker light electrical connectors.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">11</span><span>With the help of an assistant, remove the fascia (1) from the vehicle.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>With the help of an assistant, position the fascia to the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>With the help of an assistant and using firm pressure, align and push forward to engage the fascia to the rear retaining bracket (1).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Align the fascia with the retaining bracket (2) on each side in the tail light housing and using firm pressure push in to engage.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Align the fascia with the retaining brackets (3) on each quarter panel and using firm pressure push in to engage.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Install the taillamp, Refer to LAMP, TAIL STOP TURN, INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Install the fasteners (3) that secures the rear fascia assembly to the rear fascia support bracket.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Install the fastener (1) that secures the rear fascia assembly to the rear quarter. Tighten the fastener securely.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Connect the marker light electrical connectors.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Install the three push-pin retainers that secure each rear wheel house splash shield to the rear fascia assembly.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">10</span><span>Connect the negative battery cable.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">11</span><span class=\"ct-ttl\"><strong dir=\"ltr\">USE OF HEAT DURING REPAIR</strong></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-warn en-kw\">WARNING:       FCA US LLC engineering&#x27;s position on the use of heat during collision repair is as follows:</div><p style=\"margin-inline-start:40px\">Any body panel or frame component damaged which is to be repaired and reused, must be repaired using the &quot;cold straightening&quot; method. No heat may be used during the straightening process. During rough straightening prior to panel replacement, damaged panels or</p><p style=\"margin-inline-start:40px\">frame components may be heated to assist in body/frame realignment. The application of heat must be constrained to the parts which will be replaced and not allowed to affect any other components.</p><p style=\"margin-inline-start:20px\">This &quot;no heat&quot; recommendation is due to the extensive use of high strength and advanced high strength steels in FCA US LLC products. High-strength materials can be substantially and negatively affected from heat input which will not be obviously known to the repairer or consumer.</p><p style=\"margin-inline-start:20px\">Ignoring these recommendations may lead to serious compromises in the ability to protect occupants in a future collision event, reduce the engineered qualities and attributes, or decrease the durability and reliability of the vehicle.</p><p style=\"margin-inline-start:20px\">This statement supersedes any previously released information by the FCA US LLC.</p><p style=\"margin-inline-start:20px\">Failure to follow these instructions may result in serious or fatal injury.</p></div></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">12</span><span class=\"ct-ttl\"><strong dir=\"ltr\">WARNINGS</strong><small>تحذيرات</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-warn en-kw\">WARNING:   Use an Occupational Safety and Health Administration (OSHA) approved breathing filter, when spraying paint or solvents in a confined area. Failure to follow these instructions may result in possible serious or fatal injury.</div><p style=\"margin-inline-start:40px\">avoid prolonged skin contact with petroleum or alcohol based cleaning solvents. do not stand under a hoisted vehicle that is not properly supported on safety stands. Failure to follow these instructions may result in possible serious or fatal injury.</p><div class=\"ct-warn en-kw\">CAUTION:   When holes are drilled or punched in an inner body panel, verify the depth of space to the outer body panel, electrical wiring or other components. Damage to the vehicle can result.</div><p style=\"margin-inline-start:40px\">do not weld exterior panels unless combustible material on the interior of vehicle is removed from the repair area. Fire or hazardous conditions, can result. always have a fire extinguisher ready for use when welding. disconnect the negative (-) cable clamp from the battery when servicing electrical components that are live when the ignition is off. Damage to electrical system can result. do not use abrasive chemicals or compounds on painted surfaces. Damage to finish can result. do not use harsh alkaline based cleaning solvents on painted or upholstered surfaces. Damage to finish or color can result. do not hammer or pound on plastic trim panel when servicing interior trim. Plastic panels can break.</p></div></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">13</span><span class=\"ct-ttl\"><strong dir=\"ltr\">RESTRAINT WARNINGS</strong></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-warn en-kw\">WARNING:    To avoid serious or fatal injury on vehicles equipped with the Supplemental Restraint System (SRS), never attempt to repair the electrically conductive circuits or wiring components related to the SRS for which there is no MOPAR wiring repair kit. It is important to use ONLY the recommended splicing kit and procedure. For applicable and available MOPAR wiring repair kits, please visit the MOPAR Connector Web Site at the following address on the internet: (http://dto.vftis.com/mopar/disclaimer.asp). Inappropriate repairs can compromise the conductivity and current carrying capacity of those critical electrical circuits, which may cause SRS components not to deploy when required, or to deploy when not required. Only minor cuts or abrasions of wire and terminal insulation where the conductive material has not been damaged, or connector insulators where the integrity of the latching and locking mechanisms have not been compromised may be repaired using appropriate methods.</div><div class=\"ct-warn en-kw\">WARNING:    To avoid serious or fatal injury during and following any seat belt or child restraint anchor service, carefully inspect all seat belts, buckles, mounting hardware, retractors, tether straps, and anchors for proper installation, operation, or damage. Replace any belt that is cut, frayed, or torn. Straighten any belt that is twisted. Tighten any loose fasteners. Replace any belt that has a damaged or ineffective buckle or retractor. Replace any belt that has a bent or damaged latch plate or anchor plate. Replace any child restraint anchor or the unit to which the anchor is integral that has been bent or damaged. Never attempt to repair a seat belt or child restraint component. Always replace damaged or ineffective seat belt and child restraint components with the correct, new and unused replacement parts listed in the Chrysler Mopar® Parts Catalog. Failure to follow these instructions may result in possible serious or fatal injury.</div><div class=\"ct-warn en-kw\">WARNING:    To avoid serious or fatal injury on vehicles equipped with airbags, disable the supplemental restraint system before attempting any steering wheel, steering column, airbag, seat belt tensioner, impact sensor, or instrument panel component diagnosis or service. Disconnect and isolate the battery negative (ground) cable, then wait two minutes for the system capacitor to discharge before performing further diagnosis or service. This is the only sure way to disable the supplemental restraint system. Failure to take the proper precautions could result in accidental airbag deployment.</div><div class=\"ct-warn en-kw\">WARNING:    To avoid serious or fatal injury, do not attempt to dismantle an airbag unit or tamper with its inflator. Do not puncture, incinerate or bring into contact with electricity. Do not store at temperatures exceeding 93° C (200° F). An airbag inflator unit may contain sodium azide and potassium nitrate. These materials are poisonous and extremely flammable. Contact with acid, water, or heavy metals may produce harmful and irritating gases (sodium hydroxide is formed in the presence of moisture) or combustible compounds. An airbag inflator unit may also contain a gas canister pressurized to over 17.24 kPa (2500 psi). Failure to follow these instructions may result in possible serious or fatal injury.</div><div class=\"ct-warn en-kw\">WARNING:          To avoid serious or fatal injury when handling a seat belt tensioner retractor. Exercise proper care to keep fingers out from under the retractor cover and away from the seat belt webbing where it exits from the retractor cover. Failure to follow these instructions may result in possible serious or fatal injury.</div><div class=\"ct-warn en-kw\">WARNING:          To avoid serious or fatal injury, replace all Supplemental Restraint System (SRS) components only with parts specified in the Chrysler Mopar® Parts Catalog. Substitute parts may appear interchangeable, but internal differences may result in inferior occupant protection.</div><div class=\"ct-warn en-kw\">WARNING:          To avoid serious or fatal injury, the fasteners, screws, and bolts originally used for the Supplemental Restraint System (SRS) components must never be replaced with any substitutes. These fasteners have special coatings and are specifically designed for the SRS. Anytime a new fastener is needed, replace it with the correct fasteners provided in the service package or specified in the Chrysler Mopar® Parts Catalog.</div><div class=\"ct-warn en-kw\">WARNING:          To avoid serious or fatal injury when a steering column has an airbag unit attached, never place the column on the floor or any other surface with the steering wheel or airbag unit face down. Failure to follow these instructions may result in possible serious or fatal injury.</div></div><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">STANDARD PROCEDURE</strong><small>إجراء قياسي</small></span></summary><div class=\"ct-body\"></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">14</span><span class=\"ct-ttl\"><strong dir=\"ltr\">REAR FRAME RAIL REPLACEMENT</strong></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><p style=\"margin-inline-start:0px\">1 - COVER PLATE 2 - RAIL, REAR, OUTER 3 - RAIL, REAR, INNER 4 - REINFORCEMENT, REAR RAIL INNER, REAR</p><p style=\"margin-inline-start:0px\">&quot;Rail, rear, outer&quot; (2) - this portion of the rear rail assembly is not visible as it is gloved inside the &quot;rail, rear, inner&quot; (3) and the &quot;cover plate, rear rail extension&quot; (1). This rail may not be sectioned!</p><p style=\"margin-inline-start:0px\">&quot;Reinforcement, rear rail inner rear&quot; (4) - welded inside of the &quot;rail, rear, inner&quot; (3) and extends from the end of</p><p style=\"margin-inline-start:0px\">that rail to the &quot;panel, deck opening lower&quot;.</p><p style=\"margin-inline-start:0px\">&quot;Rail, rear inner&quot; may be sectioned at this location (1), greatly reducing vehicle disruption and repair costs.</p><p style=\"margin-inline-start:0px\">This partial replacement procedure presumes that all damage to the &quot;rail, rear inner&quot; is aft of the crossmember (2).</p><p style=\"margin-inline-start:0px\">The following procedure details key points of the repair. I-CAR training is presumed, and should be followed for best-practice repair procedures.</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Mount the damaged vehicle onto a structural straightening bench and check/correct any body misalignment utilizing three dimensional measuring equipment.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove all components in area of repair allowing unimpeded access for cutting and welding operations.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Trunk floor should be removed if being replaced, or the necessary welds released and the weld flange bent inboard to provide access to the rail for the butt-joint.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Using the round hole in the &quot;Rail, Rear, Inner&quot; as a point of reference, measure 125 mm (5 in.) forward for the left rail, or 150 mm (6 in.) forward for the right rail, and scribe a vertical line on the rail.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>With the vertical line just made as reference, cut off the damaged &quot;Rail, Rear, Inner&quot; taking care not to damage the &quot;Rail, Rear, Outer&quot;, using a reciprocating saw or cut-off wheel, and remove the damaged portion.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Utilize the same measuring and cutting process above to remove the replacement portion from the service part.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Using a surface conditioning disk, remove all e-coat within 25 mm (1 in.) of the cut location and de-bur the cut edge.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>If the &quot;Rail, Rear, Outer&quot; was damaged during the cutting operation, MIG-weld the damage and dress the weld.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Fabricate 19 mm (0.75 in.) weld backers from the damaged component, or the remains of the service part, and tack in place on the replacement rail section at the butt-joint location.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">10</span><span>Position and clamp the replacement rail and confirm proper position with measuring equipment.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">11</span><span>Weld the service part in position using a skip-stitch process.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">12</span><span>Complete remaining repairs in the damaged area.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">13</span><span>Clean and dress all welded areas.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">14</span><span>Apply epoxy primer to the exterior of the rail at the repair location.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">15</span><span>Apply quality body sealer to all areas previously sealed to duplicate the original appearance. Note that additional sealer may be applied to better protect the exterior exposed seams from road spray.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">16</span><span>Refinish all exposed surfaces in trunk and on underbody using quality refinish materials.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">17</span><span>Apply inner panel rust proofing, such as Mopar # 05093981AA, or equivalent, to the rail inner cavity areas in two applications with a 30-minute flash period between the applications. Pay particular attention to areas which have been welded.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">18</span><span>Reassemble vehicle and complete repairs. LEFT SIDE</span></div><p style=\"margin-inline-start:0px\">1 - HOLE 2 - 100 mm (4 in.) 3 - REINFORCEMENT, REAR RAIL INNER, REAR 4 - CUT LOCATION 125 mm (5 in.)</p><p style=\"margin-inline-start:0px\">The &quot;Reinforcement, Rear Rail Inner, Rear&quot; (3) ends 100 mm (4 in.) (2) forward of round hole (1) on inner face of &quot;Rail, Rear Inner&quot; - recommended cut location is 125 mm (5 in.) (4) from forward edge of the hole (1). RIGHT SIDE</p><p style=\"margin-inline-start:0px\">1 - 125 mm (5 in.) 2 - HOLE 3 - CUT LOCATION 150 mm (6 in.) 4 - REINFORCEMENT, REAR RAIL INNER, REAR</p><p style=\"margin-inline-start:0px\">The &quot;Reinforcement, Rear Rail Inner Rear&quot; (4) ends 125 mm (5 in.) (1) forward of round hole (2) on inner face of &quot;rail, rear inner&quot; - recommended cut location (3) is 150 mm (6 in.) from forward edge of hole (2). ADDITIONAL INFORMATION</p><p style=\"margin-inline-start:0px\">Observe all cautions and warnings per the Chrysler service information. Refer to FRAME, WARNING.</p><p style=\"margin-inline-start:0px\">Reference the Chrysler weld process chart. Refer to FRAME, TECHNICAL SPECIFICATIONS.</p><p style=\"margin-inline-start:0px\">Butt joint should be metal finished without thinning the base rail material or weldment. This is a cosmetic finishing process to disguise the repair and should have the surface coating (paint) duplicated as well.</p><p style=\"margin-inline-start:0px\">Restore corrosion protection when complete with all welding operations.</p></div><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">TECHNICAL SPECIFICATIONS</strong><small>المواصفات الفنية</small></span></summary><div class=\"ct-body\"></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">15</span><span class=\"ct-ttl\"><strong dir=\"ltr\">WELD PROCESS</strong></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><pre class=\"en-pre\">    COMPONENT                                        BODYSHELL EXTERIOR &amp; UNDERBODY\n                          TRUCK FRAME\n      PARTS                                                              PANELS\n                                        Zinc and Zinc Iron Alloy coated sheet steels\n                         GAS                          GAS                        GAS\n                                       FLUX                         MIG                      FLUX\nWELDING                 METAL                       METAL                       METAL\n                                      CORED                        BRAZE                    CORED\nPROCESS                  ARC                          ARC                        ARC\n                                       ARC                        (Note: 2)                   ARC\n                       (Note: 1)                    (Note: 1)                  (Note: 1)\n                      High Strength and Structural Quality Steels which includes HSLA, Martensitic, and\nMaterial Type\n                                                     Dual Phase materials\nMaterial Thickness\n                             2 mm - 4 mm               0.6 mm - 1.02 mm              &gt;1.02 mm - 3.0 mm\nRange\n                                                                      AWS\nELECTRODE                               AWS                                                       AWS\n                         AWS                          AWS           CLASS.          AWS\nTYPE                                   CLASS.                                                    CLASS.\n                        CLASS.                       CLASS.        ERCuSi - A      CLASS.\n(AWS SPEC.                             E71T-11                                                   E71T-11\n                        ER70S-6                      ER70S-6         Silicon       ER70S-6\nA5.18)                                 (Note 3)                                                  (Note 3)\n                                                                     Bronze\nELECTRODE\n                          0.035         0.045      0.023 - 0.025      0.035          0.035        0.045\nSIZE\nELECTRODE                            Lincoln®                                                 Lincoln®\n                       Lincoln®               Lincoln®                         Lincoln®\nMAKER                                NR-211-MP                                                 NR-211-MP\n                        245-250                                    150-155 Flat     245-250\nWIRE FEED                          110 Vertical     95-115 All                                 110 Vertical\n                        Vertical                                        &amp;           Vertical\nSPEED (in/min)                        Down            Welds                                       Down\n                         Down                                       Horizontal       Down\n                      70-90 Flat &amp; 70-90 Flat &amp;                                   70-90 Flat &amp; 70-90 Flat &amp;</pre><p style=\"margin-inline-start:40px\">Horizontal Horizontal                                       Horizontal Horizontal TRAVEL SPEED 10 (in/min)</p><pre class=\"en-pre\">  COMPONENT                                           BODYSHELL EXTERIOR &amp; UNDERBODY\n                          TRUCK FRAME\n    PARTS                                                          PANELS\nVOLTAGE                  19-20         15-18          16-19   18-19     19-20    15-18\nPOLARITY                 DCEP          DCEN           DCEP    DCEP      DCEP    DCEN\nGAS FLOW (cfh)           25-35          N/A           25-35   25-35     25-35     N/A\nELECTRICAL\n                        1/2 - 5/8      3/8 - 1/2     1/2 - 5/8     5/8 - 3/4      1/2- 5/8      3/8 - 1/2\nSTICKOUT (in)\nGAS TYPE                75% Ar           N/A         75% Ar        100% Ar        75% Ar          N/A\n                      25% CO2                     25% CO2                     25% CO2           \nTYPE OF ARC\n                      Short Circuit               Short Circuit     Pulse     Short Circuit          \nTRANSFER</pre><p style=\"margin-inline-start:0px\">These Procedure Specifications are appropriate as of this publication. Procedures may be superceeded with new spec&#x27;s at a later date.</p><p style=\"margin-inline-start:0px\">Always process to the thinner material thickness (TMT)</p><p style=\"margin-inline-start:0px\">All persons performing welding must be qualified to weld in all positions.</p><div class=\"ct-note en-kw\">NOTE:</div><div class=\"en-step\" style=\"margin-inline-start:40px\"><span class=\"ec-no\">1</span><span>Must remove Zinc Coating on both sides of metal at the weld zone.</span></div><div class=\"en-step\" style=\"margin-inline-start:40px\"><span class=\"ec-no\">2</span><span>MIG Braze welding process requires use of Pulse Arc® or STT® welding machine.</span></div><div class=\"en-step\" style=\"margin-inline-start:40px\"><span class=\"ec-no\">3</span><span>Must use Lincoln® product since E 71T-11 product differs from other suppliers.</span></div></div><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">SPECIFICATIONS</strong><small>المواصفات</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-note en-kw\">NOTE:           Frame dimensions are listed in metric scale millimeter (mm). All dimensions are from center to center of Principal Locating Point (PLP), or from center to center of PLP and fastener location.</div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">16</span><span class=\"ct-ttl\"><strong dir=\"ltr\">VEHICLE PREPARATION</strong></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><p style=\"margin-inline-start:0px\">Position the vehicle on a level work surface. Using screw or bottle jacks, adjust the vehicle PLP heights to the specified dimension above a level work surface. Vertical dimensions can be taken from the work surface to the locations indicated were applicable.</p><pre class=\"en-pre\">INDEX\n                             DESCRIPTION                                             FIGURE\nUnder Body Dimensions                                                               Refer to Fig. .\nUnder Hood                                                                          Refer to Fig. .</pre></div></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">17</span><span class=\"ct-ttl\"><strong dir=\"ltr\">CROSSMEMBER, CRADLE, ENGINE</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Disconnect and isolate the negative battery cable. If equipped with an Intelligent Battery Sensor (IBS), disconnect the IBS connector first before disconnecting the negative battery cable.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Raise and support the vehicle. Refer to HOISTING, STANDARD PROCEDURE .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the tire and wheel assemblies. Refer to REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Remove front belly pan Refer to BELLY PAN, REMOVAL.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Install the Engine Lift Fixture (special tool #8984B, Fixture, Engine Lifting) (1), Engine Lift Adapter (special tool #8984-UPD, Adapter, Engine Lift) (2) and the Engine Support Fixture (special tool #8534C, Fixture, Driveline Support) (3) and remove the engine mount bolts securing the mount to the cradle. For 3.6L, refer to INSULATOR, ENGINE MOUNT, LEFT, REMOVAL , INSULATOR, ENGINE MOUNT, RIGHT and INSULATOR, ENGINE MOUNT, REAR, REMOVAL . For 5.7L, refer to INSULATOR, ENGINE MOUNT, FRONT, REMOVAL , and INSULATOR, ENGINE MOUNT, REAR , For 6.2L, refer to INSULATOR, ENGINE MOUNT, FRONT , INSULATOR, ENGINE MOUNT, REAR , For 6.4L, refer to INSULATOR, ENGINE MOUNT, FRONT , INSULATOR, ENGINE MOUNT, REAR .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Remove the steering gear Refer to GEAR, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Remove the front brake rotors Refer to ROTOR, BRAKE, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Separate the stabilizer bar from the strut Refer to STABILIZER BAR, FRONT, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Separate the lower ball joints from the steering knuckle and the strut from the lower control arm Refer to ARM, UPPER CONTROL, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">10</span><span>Separate the wire harness (1) on right front corner of crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">11</span><span>Separate the power steering hydraulic lines, if equipped.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">12</span><span>Mark the position of the cradle on the frame (1) using a grease pencil or equivalent to aid installation.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">13</span><span>Support the cradle with a suitable lifting device.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">14</span><span>Remove the bolts (2) and remove the cradle (1).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">15</span><span>If necessary, remove the front stabilizer bar (2). Refer to STABILIZER BAR, FRONT, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">16</span><span>If necessary, remove the lower control arms (3) Refer to ARM, LOWER CONTROL, RWD, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">17</span><span>If necessary, remove the tension struts (1) Refer to STRUT, TENSION, REMOVAL .</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>If necessary, install the tension struts (1) Refer to STRUT, TENSION, INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>If necessary, install the lower control arms (3) Refer to ARM, LOWER CONTROL, RWD, INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>If necessary, install the front stabilizer bar (2) Refer to STABILIZER BAR, FRONT, INSTALLATION</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Using a suitable lifting device, position the cradle (1) back onto the vehicle using the marks made during removal and install the bolts (2).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Tighten the bolts (2) to the proper torque specifications.Refer to TORQUE SPECIFICATIONS.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Position the power steering lines back into place, if equipped.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Position the wire harness (1) back into place.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Connect the lower control arms to the struts and connect the lower ball joints to the steering knuckles</span></div><p style=\"margin-inline-start:10px\">Refer to ARM, LOWER CONTROL, RWD, INSTALLATION .</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Connect the stabilizer bar back onto the strut Refer to STABILIZER BAR, FRONT, INSTALLATION</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">10</span><span>Install the front brake rotors Refer to ROTOR, BRAKE, INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">11</span><span>Install the steering gear Refer to GEAR, INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">12</span><span>Install the engine mount bolts securing the mounts to the cradle and remove the engine lift fixture Refer to INSULATOR, ENGINE MOUNT, FRONT, INSTALLATION, 5.7L .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">13</span><span>Install the front belly pan Refer to BELLY PAN, INSTALLATION.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">14</span><span>Install the tire and wheel assemblies Refer to INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">15</span><span>Lower the vehicle and connect the negative battery cable. If equipped with an Intelligent Battery Sensor (IBS), connect the IBS connector to the negative battery cable.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">16</span><span>Perform vehicle alignment Refer to WHEEL ALIGNMENT, STANDARD PROCEDURE .</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">18</span><span class=\"ct-ttl\"><strong dir=\"ltr\">CROSSMEMBER, REAR</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Remove the rear axle differential or. Refer to REMOVAL . Refer to REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Separate the rear brake cables from the front cable as necessary. Refer to CABLE, PARKING BRAKE, REAR, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the bolt and the parking brake cable guide bracket.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Disconnect the shock wire harness and unclip the wire harness from the rear crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Remove fuel filler tube Refer to TUBE, FUEL TANK FILLER, REMOVAL .</span></div><div class=\"ct-warn en-kw\">WARNING:        Before opening fuel system, review all Warnings and Cautions.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>On each side of vehicle, remove shock absorber lower bolt (2) and nut (4)</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Using a grease pencil or equivalent, mark the position (2) of the rear suspension crossmember at all four isolator bushing (3) locations to aid in installation.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Position an extra pair of jack stands under and support forward end of engine cradle to help stabilize vehicle during rear suspension removal/installation.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Using a suitable lifting device, support the rear suspension crossmember.</span></div><div class=\"ct-note en-kw\">NOTE:          The rear springs can be lowered with the rear suspension crossmember. Installation of the rear suspension crossmember will require the rear springs to be installed after the crossmember is bolted properly into the vehicle.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">10</span><span>Remove the four bolts (2 and 3).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">11</span><span>Remove the retainer plates (4).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">12</span><span>Slowly lower the rear suspension crossmember (1) and guide the brake calipers up through the suspension, following brake hose path. Support the calipers above the crossmember with wire when the crossmember is lowered.</span></div><div class=\"ct-note en-kw\">NOTE:          The crossmember isolators can be serviced without removing any additional components.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">13</span><span>If necessary, remove the isolators from the crossmember Refer to ISOLATOR, REAR CROSSMEMBER, SPRING LINK, REMOVAL.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">14</span><span>If necessary, remove the rear stabilizer bar from the crossmember Refer to STABILIZER BAR, REAR SUSPENSION, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">15</span><span>If necessary, remove the spring link from the crossmember Refer to LINK, TOE, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">16</span><span>If necessary, remove the toe link from the crossmember Refer to LINK, TOE, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">17</span><span>If necessary, remove the camber link from the crossmember Refer to LINK, TOE, REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">18</span><span>If necessary remove the rear knuckle from the crossmember Refer to KNUCKLE, REAR, REMOVAL .</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Guide the brake calipers up through the suspension and slowly position the rear suspension crossmember (1) into the vehicle. As crossmember is raised, align shocks with pockets in spring links.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Loosely install the front bolts (2).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Position the retainer plates (4) back into place and loosely install the rear bolts (3).</span></div><div class=\"ct-note en-kw\">NOTE:          There are four crossmember mounting bolts. The rear bolts are longer than the front bolts. Do not interchange bolts.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Install the rear springs. Refer to SPRING(S), INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Once mounts are lined up with location marks, on both sides of vehicle, measure distance (1) between the tension link (2) and weld flange (3) on body directly in front of it, just outboard of the front mount bushing (4). This distance must be at least 12 mm to allow proper clearance for suspension movement. If distance is less than 12 mm on either side of vehicle, shift that side of rear crossmember directly rearward until distance is 12 mm or greater. To do so, loosen 3 mounting bolts slightly, leaving one on opposite side of shift snugged to pivot off of. Shift crossmember rearward and snug loosened bolts. Measure opposite side to be sure it still maintains minimum 12 mm distance.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Align the rear suspension crossmember with the reference marks made previously and tighten the rear suspension crossmember to body bolts to the proper torque specifications. Refer to TORQUE SPECIFICATIONS.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Install the lower shock bolt (2) and nut (4) and tighten to the proper torque specifications. Refer to TORQUE SPECIFICATIONS .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Install the fuel filler tube Refer to TUBE, FUEL TANK FILLER, INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Route the wire harness and connect all wire harness connectors.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">10</span><span>Install the parking brake cable guide bracket and bolt.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">11</span><span>Connect the rear brake cables back to the front as necessary Refer to CABLE, PARKING BRAKE, REAR, INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">12</span><span>Install the rear axle differential or. Refer to INSTALLATION . Refer to INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">13</span><span>Install the rear brake pads and calipers Refer to PADS, BRAKE, INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">14</span><span>Install the muffler Refer to MUFFLER, EXHAUST, INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">15</span><span>Install the tire and wheel assembly Refer to INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">16</span><span>Check the wheel alignment and adjust if necessary Refer to WHEEL ALIGNMENT, STANDARD PROCEDURE .</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">19</span><span class=\"ct-ttl\"><strong dir=\"ltr\">CROSSMEMBER, TRANSMISSION</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><p style=\"margin-inline-start:0px\">Manual Transmission</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Support the transmission with a suitable lifting device.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove the mount fasteners (1).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the frame bolts (2) and remove the crossmember.</span></div><p style=\"margin-inline-start:0px\">Automatic Transmission</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Support the transmission with a suitable lifting device.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove the mount fasteners (1).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the frame bolts (2) and remove the crossmember.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><p style=\"margin-inline-start:0px\">Manual Transmission</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Install the crossmember and install the bolts (2) and tighten the bolts to the proper torque specifications.</span></div><p style=\"margin-inline-start:10px\">Refer to TORQUE SPECIFICATIONS.</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Install the mount fasteners (1) and tighten the bolts to the proper torque specifications. Refer to TORQUE SPECIFICATIONS.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the transmission support.</span></div><p style=\"margin-inline-start:0px\">Automatic Transmission</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Install the crossmember and install the bolts (2) and tighten the bolts to the proper torque specifications.</span></div><p style=\"margin-inline-start:10px\">Refer to TORQUE SPECIFICATIONS.</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Install the mount fasteners (1) and tighten the bolts to the proper torque specifications. Refer to TORQUE SPECIFICATIONS.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the transmission support.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">20</span><span class=\"ct-ttl\"><strong dir=\"ltr\">ISOLATOR, REAR CROSSMEMBER, DIFFERENTIAL</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Remove the rear crossmember Refer to CROSSMEMBER, TRANSMISSION, REMOVAL.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove bolts (1) from bushing prior to removal.</span></div><div class=\"ct-note en-kw\">NOTE:           Prior to using Special Tool (special tool #9520, Remover/Installer, Bushing), lubricate Bolt (1) threads to provide ease of use and promote tool longevity.</div><div class=\"ct-note en-kw\">NOTE:           When installing Thrust Bearing (6), be sure to place hardened side toward Bolt head.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Assemble tools (See following list) over bushing as shown. (1) Bolt (2) Nut (3) Washer (4) Receiver (special tool #9520-4, Cup, Receiver) (5) Remover (special tool #9520-3, Remover, Bushing) (6) Thrust Bearing</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>While holding Nut (2) from rotating, using hand tools , tighten Bolt (1) until Remover (5) comes in contact with bushing and Receiver (4) sets squarely against crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Continue to tighten Bolt (1), pressing bushing out of crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Remove tools with bushing.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-note en-kw\">NOTE:          It is important that tapered end (3) of bushing be installed first into forward end of crossmember to ease installation.</div><div class=\"ct-note en-kw\">NOTE:          When installing Thrust Bearing (7), be sure to place hardened side toward Bolt head.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Insert tapered end of NEW bushing (3) into forward end of crossmember bushing bore.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Assemble tools (See following list) through crossmember and bushing as shown. (1) Bolt (2) Disc (special tool #9520-1, Installer Disc) (3) Bushing (4) Nut (5) Washer (6) Installer (special tool #9520-2A, Installer, Bushing) (7) Thrust Bearing</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Insert Installer (6) into end of bushing and Disc (2) into opposite end of crossmember bushing bore.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>While holding Nut (4) from rotating, tighten Bolt (1) using hand tools , pressing bushing into crossmember. Stop when Installer (6) bottoms against bushing bore.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Remove tools.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Install the rear crossmember Refer to CROSSMEMBER, TRANSMISSION, INSTALLATION.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">21</span><span class=\"ct-ttl\"><strong dir=\"ltr\">ISOLATOR, REAR CROSSMEMBER, FRONT MOUNT</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Remove the rear crossmember. Refer to CROSSMEMBER, TRANSMISSION, REMOVAL.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove travel limiter (2) from bushing inner metal sleeve (1). To do so, use an appropriate grinding tool to remove inner metal sleeve material until limiter can be safely removed.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Slide Support (2), Special Tool (special tool #9031-9, Clamp), into end of crossmember (3) surrounding bushing bore as shown.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Snug set-screws (1) securing Support (2) to crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Insert Brace (1), Special Tool (special tool #9031-10, Brace), between Support (special tool #9031-9, Clamp) (3) and bushing bore flange (2) matching step in Brace to bore flange.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Snug set-screws (2) against Brace (special tool #9031-10, Brace). Do not overtighten set-screws as they will distort and bend bushing bore flange.</span></div><div class=\"ct-note en-kw\">NOTE:          Prior to using Press (1), Special Tool (special tool #C-4212F, Press, Ball Joint) Ball Joint Press Installer/Removal, lubricate screw-drive threads to provide ease of use and promote tool longevity.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Assemble tools (See following list) over bushing as shown. Ensure Remover lies between ridges (3) on bushing to properly contact bushing can. (1) Press (special tool #C-4212F, Press, Ball Joint) (2) Remover (special tool #9031-5A, Remover, Bushing) (4) Receiver (special tool #9031-8A, Receiver, Bushing)</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Tighten Press (1) screw-drive, pressing bushing out of crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Remove all tools.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-warn en-kw\">CAUTION:     Prior to bushing installation, inspect the bushing to make sure it is the correct side bushing for the job. Left side bushings have the travel limiter (1) tipped to the right in relationship to the bushing (4) can flange as shown. Right side bushings have the travel limiter (2) tipped to the left in relationship to the bushing (3) can flange as shown. Once installed, the travel limiters with face slightly outward from straight-ahead position.</div><div class=\"ct-warn en-kw\">CAUTION:     It is very important that bushing be installed in same position as original to maintain vehicle ride quality and bushing longevity. That is why bushing, once installed, needs to closely match reference marks applied upon removal of original bushing.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Position bushing on crossmember bushing bore aligning bushing can flange with reference marks applied during removal.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Assemble tools (See following list) over bushing and crossmember as shown. (2) Receiver (special tool #9031-6, Receiver) (3) Press (special tool #C-4212F, Press, Ball Joint) (4) Installer (special tool #9031-7A, Installer, Bushing)</span></div><div class=\"ct-note en-kw\">NOTE:          Ensure Installer (3), Special Tool (special tool #9031-7A, Installer, Bushing), is positioned that it will clear compression link bracket (1) while bushing is being installed.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Tighten Press (2) screw-drive, pressing bushing into crossmember. Install bushing until bushing can flange contacts surface of crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Remove tools.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Verify bushing closely lines up with reference marks applied during removal.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Install the rear crossmember. Refer to CROSSMEMBER, TRANSMISSION, INSTALLATION.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">22</span><span class=\"ct-ttl\"><strong dir=\"ltr\">ISOLATOR, REAR CROSSMEMBER, REAR MOUNT</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><p style=\"margin-inline-start:0px\">1 - BUSHING CAN FLANGE 2 - MARKER OR CRAYON 3 - CROSSMEMBER</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Remove the rear crossmember Refer to CROSSMEMBER, TRANSMISSION, REMOVAL.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>As an installation reference, carefully mark location of bushing requiring removal on crossmember (around bushing can flange) using a marker or crayon. Do not use a scratch awl to mark location.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Slide Support (2), Special Tool (special tool #9031-11, Clamp), into end of crossmember (3) surrounding bushing bore as shown.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Snug set-screws (1) securing Support (2) to crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Insert Brace (1), Special Tool (special tool #9031-12, Brace), between Support (special tool #9031-11, Clamp) (3) and bushing bore flange (2) matching angle cut in Brace to bore flange.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Snug set-screws (1) against Brace (special tool #9031-12, Brace). Do not overtighten set-screws as they will distort and bend bushing bore flange.</span></div><div class=\"ct-note en-kw\">NOTE:          Prior to using Press (1), Special Tool (special tool #C-4212F, Press, Ball Joint), lubricate screw-drive threads to provide ease of use and promote tool longevity.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Assemble tools (See following list) over bushing as shown. (1) Press (special tool #C-4212F, Press, Ball Joint)</span></div><p style=\"margin-inline-start:20px\">(2) Remover (special tool #9031-2, Remover, Bushing) (3) Receiver (special tool #9031-1, Bushing Removal Receiver)</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Tighten Press (1) screw-drive, pressing bushing out of crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Remove all tools.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-warn en-kw\">CAUTION:       It is very important that bushing be installed in same position as original to maintain vehicle ride quality and bushing longevity. That is why bushing, once installed, needs to closely match reference marks applied upon removal of original bushing.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Position bushing on crossmember bushing bore aligning bushing can flange (3) with reference marks applied during removal.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Assemble tools (See following list) over bushing (3) and crossmember as shown. (1) Press (special tool #C-4212F, Press, Ball Joint) (2) Receiver (special tool #9031-3, Receiver, Bushing) (4) Installer (special tool #9031-4, Installer, Bushing)</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Tighten Press (1) screw-drive, pressing bushing into crossmember. Install bushing until bushing can flange contacts surface of crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Remove tools.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Install the rear crossmember Refer to CROSSMEMBER, TRANSMISSION, INSTALLATION.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">23</span><span class=\"ct-ttl\"><strong dir=\"ltr\">ISOLATOR, REAR CROSSMEMBER, SPRING LINK</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Raise and support the vehicle. Refer to HOISTING, STANDARD PROCEDURE .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Access and remove rear spring on side of repair Refer to SPRING(S), REMOVAL .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>If servicing right side bushing, disconnect headlamp leveling sensor (1) link at spring link (3), if equipped.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Remove bolt and nut (1) fastening spring link (4) to crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Position spring link downward, away from bushing in crossmember.</span></div><p style=\"margin-inline-start:10px\">1 - BUSHING 2 - REMOVER 9032-2 3 - PRESS C-4212F 4 - RECEIVER 9032-1</p><div class=\"ct-note en-kw\">NOTE:           Prior to using Press (3), Special Tool (special tool #C-4212F, Press, Ball Joint), lubricate screw-drive threads to provide ease of use and promote tool longevity.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Assemble tools over bushing as shown (See list). Ensure Receiver, Special Tool (special tool #9032-1, Receiver, Bushing), sets against crossmember and not welds. (2) Remover (special tool #9032-2, Receiver, Bushing) (3) Press (special tool #C-4212F, Press, Ball Joint) (4) Receiver (special tool #9032-1, Receiver, Bushing)</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Tighten Press screw-drive, pressing bushing out of crossmember.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><p style=\"margin-inline-start:0px\">1 - BUSHING 2 - REMOVER/INSTALLER 9032-2 3 - PRESS C-4212F 4 - RECEIVER 9032-3</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Position bushing (1) over rear of crossmember bushing bore.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Assemble tools over bushing and crossmember as shown (See list). Ensure Receiver, Special Tool (special tool #9032-3, Pusher, Bushing), is positioned to avoid welds on rear of crossmember bushing bore. (2) Remover/Installer (special tool #9032-2, Receiver, Bushing) (3) Press (special tool #C-4212F, Press, Ball Joint) (4) Receiver (special tool #9032-3, Pusher, Bushing)</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Tighten Press screw-drive, pressing bushing into crossmember. Install bushing until screw-drive stops, when bushing contacts Receiver on opposite side of crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Remove tools.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Swing spring link up to bushing in crossmember and install bolt and nut (1) fastening spring link (4) to crossmember. Do not tighten bolt at this time.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>If servicing right side bushing, connect headlamp leveling sensor (1) link at spring link (3), if equipped.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Install rear spring as well as all components necessary to access it. Refer to SPRING(S), INSTALLATION .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">8</span><span>Remove the support and lower the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">9</span><span>Position vehicle on alignment rack/drive-on lift. Raise vehicle as necessary to access mounting bolt.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">10</span><span>Tighten spring link bolt (1) at crossmember to. Refer to TORQUE SPECIFICATIONS .</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">11</span><span>Perform wheel alignment. Refer to WHEEL ALIGNMENT, STANDARD PROCEDURE .</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">25</span><span class=\"ct-ttl\"><strong dir=\"ltr\">BELLY PAN</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-note en-kw\">NOTE:          Base model shown, SRT models similar.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Raise and support the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove the four fasteners (2) that secure the rear belly pan (1) to the underside of the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Pull the rear belly pan (1) rearward out of the from the front belly pan (3) to remove from the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Remove the six screws (4) that secure the front belly pan (2) to the underside of the vehicle&#x27;s front fascia.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Remove the three screws (1) that secure the front belly pan (2) to the underside of the vehicle&#x27;s wheelhouse inner. Repeat for the other side.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Remove the four push pin fasteners (3) that secure the front belly pan (2) to the underside of the vehicle&#x27;s lower crossmember. Repeat for the other side.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Remove the front belly pan (2) from the underside of the vehicle.</span></div></div></div></details><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">INSTALLATION</strong><small>التركيب</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-note en-kw\">NOTE:          Base model shown, SRT models similar.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Position the front belly pan (2) to the underside of the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Install the four push pin fasteners (3) that secure the front belly pan (2) to the underside of the vehicle&#x27;s lower crossmember.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Install the six screws (4) that secure the front belly pan (2) to the underside of the vehicle&#x27;s front fascia.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Install the three screws (1) that secure the front belly pan (2) to the underside of the vehicle&#x27;s wheelhouse inner. Tighten the screws securely. Repeat for the other side.</span></div><div class=\"ct-note en-kw\">NOTE:            During installation, ensure rear belly pan is shingled underneath front belly pan. Failure to do so may result in damage to belly pan.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">5</span><span>Position the rear belly pan (1) to the underside of the vehicle and to the front fascia (3).</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">6</span><span>Install the fasteners (2) that secure the rear belly pan (1) to the underside of the vehicle. Tighten the fasteners securely.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">7</span><span>Lower the vehicle.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">26</span><span class=\"ct-ttl\"><strong dir=\"ltr\">SHIELD, UNDERBODY</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"ct-note en-kw\">NOTE:          Right side shown, left side typical.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Raise and support the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove the two fasteners (3) that secure the underbody shield (1) to the rear wheelhouse splash shield.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the six retaining nuts (2) that secure the underbody shield (1) to the vehicle underbody.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Remove the underbody shield from the vehicle. INSTALLATION</span></div><div class=\"ct-note en-kw\">NOTE:          Right side shown, left side typical.</div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Position the underbody shield (1) to the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Install the six retaining nuts (2) that secure the underbody shield (1) to the vehicle underbody. Tighten the nuts securely.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Install the two fasteners (3) that secure the underbody shield (1) to the rear wheelhouse splash shield.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">4</span><span>Lower the vehicle.</span></div></div></div></details></div></details><details class=\"pcm-component-details ct-d en-topic\"><summary><span class=\"ec-no\">27</span><span class=\"ct-ttl\"><strong dir=\"ltr\">SHIELD, REAR MOUNT</strong></span></summary><div class=\"ct-body\"><details class=\"pcm-component-details ct-d en-sec lv2\"><summary><span class=\"ct-ttl\"><strong dir=\"ltr\">REMOVAL</strong><small>الفك</small></span></summary><div class=\"ct-body\"><div class=\"en-raw\" dir=\"ltr\"><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Raise and support the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Remove the three retaining nuts (2) that secure the rear underbody shield/panel (1) to the tire tub area located forward of the rear fascia.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Remove the rear underbody shield/panel (1) from the vehicle.</span></div><p style=\"margin-inline-start:0px\">INSTALLATION</p><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">1</span><span>Position the rear underbody shield/panel (1) to the vehicle.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">2</span><span>Install the three retaining nuts (2) that secure the underbody shield (1) to the vehicle underbody. Tighten the nuts securely.</span></div><div class=\"en-step\" style=\"margin-inline-start:0px\"><span class=\"ec-no\">3</span><span>Lower the vehicle.</span></div><p style=\"margin-inline-start:40px\">Article GUID: A00910337</p></div></div></details></div></details>";
